-- DEMO ONLY · seed_history.sql · optional sample history for analytics
-- Nov 2025 to Oct 2026. Generated once with a fixed random seed, then frozen.
-- Run AFTER seed.sql on the kb-demo project. To reset, run seed.sql then this.
-- NEVER run this on the live project.
--
-- Keeps every November 2026 figure from seed.sql unchanged:
--   * every payment here is dated before 1 Nov 2026 (Collected in Nov stays 37,000)
--   * every stay here is completed (balance 0) or cancelled (balance 0),
--     so To collect stays 5,000
--   * no stay here overlaps Meena (30 Oct) or any later stay
-- Bill numbers: KB-2025-xxxx for bookings made in 2025, KB-2026-0001..0040 for
-- bookings made in 2026 before Lakshmi's KB-2026-0041 in seed.sql.
-- Includes past stays for Lakshmi (Thai Poosam) and Priya (May holiday), so both
-- show as returning guests, plus 3 cancellations and one voided payment.
-- All phone numbers start with 00000 and cannot belong to a real person.
-- =============================================================================

begin;

do $$
begin
  if not exists (select 1 from public.stays where bill_no = 'KB-2026-0041') then
    raise exception 'Run seed.sql first.';
  end if;
  if exists (select 1 from public.stays where bill_no = 'KB-2026-0001') then
    raise exception 'History is already loaded. Run seed.sql to reset, then this file.';
  end if;
end $$;


